-- Alerts (ARCHITECTURE §5.2; docs/plan.md §1.13, stream M8b): what an agent noticed, with its
-- evidence and the agent version that raised it; first use, the Materials pack's price alerts.
-- A new table only, so the previous Worker keeps working. Generated by drizzle-kit; the grants and
-- row-level security at the end are hand-written, as in 0002 and 0005.
CREATE TABLE "alert" (
	"id" uuid PRIMARY KEY DEFAULT uuid_generate_v7() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"pack" text,
	"kind" text NOT NULL,
	"subject_type" text NOT NULL,
	"subject_id" uuid NOT NULL,
	"severity" text NOT NULL,
	"title" text NOT NULL,
	"body" text NOT NULL,
	"evidence" jsonb NOT NULL,
	"facts" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"dollar_impact" numeric(14, 4),
	"currency" text DEFAULT 'USD' NOT NULL,
	"dedupe_key" text,
	"status" text DEFAULT 'open' NOT NULL,
	"raised_by_run_id" uuid,
	"agent_version_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"resolved_at" timestamp with time zone,
	"resolved_by" uuid,
	CONSTRAINT "alert_id_tenant_key" UNIQUE("id","tenant_id"),
	CONSTRAINT "alert_severity_check" CHECK ("alert"."severity" in ('info', 'warning', 'critical')),
	CONSTRAINT "alert_status_check" CHECK ("alert"."status" in ('open', 'accepted', 'dismissed')),
	CONSTRAINT "alert_evidence_check" CHECK (jsonb_typeof("alert"."evidence") = 'array' and jsonb_array_length("alert"."evidence") > 0)
);
